95:   loadData(): void {
96:     this.solicitudesCorreosService.get('solicitud?query=EstadoTipoSolicitudId.TipoSolicitud.Id:40,Activo:true&limit=0&sortby=Id&order=desc').subscribe(res => {
97:       if (res !== null) {
98:         const data = <Array<any>><unknown>res;
99:         const formattedData = data.map(item => ({
100:           id: item.Id,
101:           procesoAdminicion: item.EstadoTipoSolicitudId.TipoSolicitud.Nombre,
102:           fecha: this.formatDate(item.FechaRadicacion),
103:           estado: item.EstadoTipoSolicitudId.EstadoId.Nombre,
104:           referencia: JSON.parse(item.Referencia),
105:           estadoStyle: this.getEstadoStyle(item.EstadoTipoSolicitudId.EstadoId.Id)
106:         }));
107:   
108:         formattedData.sort((a, b) => {
109:           if (a.estado === 'Radicado' && b.estado !== 'Radicado') {
110:             return -1;
111:           } else if (a.estado !== 'Radicado' && b.estado === 'Radicado') {
112:             return 1;
113:           } else {
114:             const dateA = new Date(a.fecha);
115:             const dateB = new Date(b.fecha);
116:             return dateB.getTime() - dateA.getTime();
117:           }
118:         });
119:   
120:         this.dataSource = new MatTableDataSource(formattedData);
121:         this.dataSource.paginator = this.paginator;
122:       }
123:     });
124:   }
