126:   getEstadoStyle(EstadoId: number): { color: string } {
127:     switch (EstadoId) {
128:       case 105:
129:         return { color: 'var(--success-accent)' };
130:       case 100:
131:         return { color: 'var(--danger-base)' };
132:       default:
133:         return { color: 'black'};
134:     }
