137:   formatDate(dateString: string): string {
138:     const date = new Date(dateString);
139:     const day = String(date.getUTCDate()).padStart(2, '0');
140:     const month = String(date.getUTCMonth() + 1).padStart(2, '0');
141:     const year = date.getUTCFullYear();
142:     return `${day}/${month}/${year}`;
143:   }
