21: 
22:   post(endpoint:string, element:any) {
23:     this.requestManager.setPath('SOLICITUDES_ADMINISTRACION');
24:     return this.requestManager.post(endpoint, element);
25:   }
26: 
27:   put(endpoint:string, element:any) {
28:     this.requestManager.setPath('SOLICITUDES_ADMINISTRACION');
29:     return this.requestManager.put(endpoint, element);
30:   }
31: 
32:   delete(endpoint:string, element:any) {
33:     this.requestManager.setPath('SOLICITUDES_ADMINISTRACION');
34:     return this.requestManager.delete(endpoint, element.Id);
35:   }
36: 
37:   cargarDatos(file: File): Observable<any[]> {
38:     return new Observable<any[]>(observer => {
39:       Papa.parse(file, {
40:         header: true,
41:         complete: (result: any) => {
42:           observer.next(result.data);
43:           observer.complete();
44:         },
45:         error: (error: any) => {
46:           observer.error(error);
47:         }
48:       });
49:     });
50:   }
51: 
52:   descargarDatos(data: any[], chunkSize: number = 20): Observable<void> {
53:     return new Observable<void>(observer => {
54:       const workbook = XLSX.utils.book_new();
55: 
56:       for (let i = 0; i < data.length; i += chunkSize) {
57:         const chunk = data.slice(i, i + chunkSize);
58:         const worksheet = XLSX.utils.json_to_sheet(chunk);
59:         XLSX.utils.book_append_sheet(workbook, worksheet, `Sheet${Math.floor(i / chunkSize) + 1}`);
60:       }
61: 
62:       const excelBuffer = XLSX.write(workbook, { bookType: 'xlsx', type: 'array' });
63:       const blob = new Blob([excelBuffer], { type: 'application/octet-stream' });
64:       saveAs(blob, 'solicitudes_correos.xlsx');
65: 
66:       observer.next();
67:       observer.complete();
68:     });
69:   }
70: }

